import{_ as s,o as a,c as r,a2 as o}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"🎮 Premiers pas","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/guide-joueur/01-premiers-pas.md","filePath":"gitbook/guide-joueur/01-premiers-pas.md"}'),t={name:"gitbook/guide-joueur/01-premiers-pas.md"};function i(n,e,u,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="🎮-premiers-pas" tabindex="-1">🎮 Premiers pas <a class="header-anchor" href="#🎮-premiers-pas" aria-label="Permalink to &quot;🎮 Premiers pas&quot;">​</a></h1><h2 id="vous-etes-nouveau" tabindex="-1">Vous êtes nouveau ? <a class="header-anchor" href="#vous-etes-nouveau" aria-label="Permalink to &quot;Vous êtes nouveau ?&quot;">​</a></h2><p>Bienvenue au Carnaval ! Carnival of the Deads est un jeu de déduction sociale et de bluff joué sur Discord. Pas de panique — les règles sont simples une fois que vous avez compris le principe.</p><h2 id="le-principe-en-3-points" tabindex="-1">Le principe en 3 points <a class="header-anchor" href="#le-principe-en-3-points" aria-label="Permalink to &quot;Le principe en 3 points&quot;">​</a></h2><ol><li><strong>Vous portez un masque</strong> qui vous donne des pouvoirs.</li><li><strong>Certains joueurs sont des Revenants</strong> (le camp secret) — vous ne savez pas qui.</li><li><strong>Éliminez l&#39;autre camp</strong> pour gagner.</li></ol><h2 id="les-phases-de-jeu" tabindex="-1">Les phases de jeu <a class="header-anchor" href="#les-phases-de-jeu" aria-label="Permalink to &quot;Les phases de jeu&quot;">​</a></h2><p>Une partie alterne entre 4 phases :</p><ol><li>🌙 <strong>Nuit</strong> : les joueurs utilisent leurs pouvoirs secrets en MP.</li><li>📢 <strong>Résolution</strong> : le bot affiche les résultats (sans dire qui a fait quoi).</li><li>💬 <strong>Débats</strong> : discussion libre (5 minutes). Vous pouvez vous déplacer entre les salons.</li><li>☀️ <strong>Actions de Jour</strong> : les joueurs utilisent leurs pouvoirs publics.</li><li>⚔️ <strong>Duels</strong> : les joueurs se défient en combat direct.</li></ol><h2 id="ce-que-vous-devez-savoir" tabindex="-1">Ce que vous devez savoir <a class="header-anchor" href="#ce-que-vous-devez-savoir" aria-label="Permalink to &quot;Ce que vous devez savoir&quot;">​</a></h2><h3 id="vos-pv-sont-secrets" tabindex="-1">Vos PV sont secrets <a class="header-anchor" href="#vos-pv-sont-secrets" aria-label="Permalink to &quot;Vos PV sont secrets&quot;">​</a></h3><p>Vous connaissez vos propres PV, mais pas ceux des autres. Seul le total de dégâts reçus est public.</p><h3 id="les-camps-sont-secrets" tabindex="-1">Les camps sont secrets <a class="header-anchor" href="#les-camps-sont-secrets" aria-label="Permalink to &quot;Les camps sont secrets&quot;">​</a></h3><p>Vous ne savez pas qui est Revenant sauf si un pouvoir vous le révèle.</p><h3 id="les-masques-se-brisent" tabindex="-1">Les masques se brisent <a class="header-anchor" href="#les-masques-se-brisent" aria-label="Permalink to &quot;Les masques se brisent&quot;">​</a></h3><p>Quand un masque atteint 0 PV, le joueur est K.O. Son identité est révélée (pas son camp).</p><h3 id="vous-pouvez-laisser-une-rumeur" tabindex="-1">Vous pouvez laisser une rumeur <a class="header-anchor" href="#vous-pouvez-laisser-une-rumeur" aria-label="Permalink to &quot;Vous pouvez laisser une rumeur&quot;">​</a></h3><p>Quand votre masque se brise, vous pouvez laisser un dernier message (200 caractères). C&#39;est votre dernière chance d&#39;influencer la partie.</p><h2 id="conseils-pour-commencer" tabindex="-1">Conseils pour commencer <a class="header-anchor" href="#conseils-pour-commencer" aria-label="Permalink to &quot;Conseils pour commencer&quot;">​</a></h2><ol><li><strong>Lisez le Grimoire des Masques</strong> (envoyé en MP au début de la partie). C&#39;est votre bible.</li><li><strong>Écoutez les discussions</strong> pendant les Débats. Les indices sont partout.</li><li><strong>Ne accusez pas sans preuve</strong> — les Reventants mentent aussi bien que les Vivants.</li><li><strong>Utilisez vos pouvoirs avec stratégie</strong> — ne les gaspillez pas.</li><li><strong>Amusez-vous</strong> — c&#39;est un jeu. Le plus important, c&#39;est de s&#39;amuser.</li></ol>',19)])])}const v=s(t,[["render",i]]);export{m as __pageData,v as default};
